class Solution:
    def sumOfPower(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7
        n = len(nums)
        dp = [[0] * (k + 1) for _ in range(n + 1)]
        dp[0][0] = 1
        for x in nums:
            if x > k:
                continue
            nd = [row[:] for row in dp]
            for c in range(n):
                for s in range(k, x - 1, -1):
                    nd[c + 1][s] = (nd[c + 1][s] + dp[c][s - x]) % MOD
            dp = nd
        ans = 0
        for c in range(n + 1):
            ans = (ans + dp[c][k] * pow(2, n - c, MOD)) % MOD
        return ans

