class Solution {
public:
    int sumOfPower(vector<int>& nums, int k) {
        const long long MOD = 1e9 + 7;
        int n = nums.size();
        vector<vector<long long>> dp(n + 1, vector<long long>(k + 1, 0));
        dp[0][0] = 1;
        for (int x : nums) {
            if (x > k) continue;
            auto nd = dp;
            for (int c = 0; c < n; c++)
                for (int s = k; s >= x; s--)
                    nd[c + 1][s] = (nd[c + 1][s] + dp[c][s - x]) % MOD;
            dp = nd;
        }
        long long ans = 0;
        for (int c = 0; c <= n; c++) {
            long long p = 1;
            for (int t = 0; t < n - c; t++) p = p * 2 % MOD;
            ans = (ans + dp[c][k] * p) % MOD;
        }
        return ans;
    }
};

