var sumOfPower = function(nums, k) {
    const MOD = 1e9 + 7, n = nums.length;
    const mul = (a, b) => { a %= MOD; b %= MOD; let r = 0;
        while (b > 0) { if (b & 1) r = (r + a) % MOD; a = (a * 2) % MOD; b >>>= 1; } return r; };
    let dp = Array.from({ length: n + 1 }, () => new Array(k + 1).fill(0));
    dp[0][0] = 1;
    for (const x of nums) {
        if (x > k) continue;
        const nd = dp.map(r => r.slice());
        for (let c = 0; c < n; c++)
            for (let s = k; s >= x; s--)
                nd[c + 1][s] = (nd[c + 1][s] + dp[c][s - x]) % MOD;
        dp = nd;
    }
    let ans = 0;
    for (let c = 0; c <= n; c++) {
        let p = 1;
        for (let t = 0; t < n - c; t++) p = p * 2 % MOD;
        ans = (ans + mul(dp[c][k], p)) % MOD;
    }
    return ans;
};

